/// read_proc_file, which reads a whole kernel-generated file through direct system calls.

#pragma once

#include <cstddef>
#include <optional>
#include <string>
#include <string_view>

namespace rasp::util {

/// Reads the file at `path` to its end, through direct system calls, so no interposed libc function stands between
/// the runtime and the kernel's answer.
///
/// The files this reads are generated by the kernel at read time, on the filesystems that exist to carry them:
/// procfs, sysfs and selinuxfs. A file anywhere else — a copy written to storage, a memfd — is refused, whatever
/// size it claims: a stored copy is not the kernel's answer, and neither is an empty one, which would otherwise
/// read as a scan that found nothing.
///
/// The file is read in chunks, so a size of 0 doesn't mean empty. It is opened with close-on-exec, so it never leaks
/// into a process the app starts.
///
/// @param path The file to read.
/// @param limit The largest content accepted, in bytes.
/// @return The content of the file, or nothing when it can't be opened, read or closed, when it doesn't live on one
/// of the kernel's own filesystems (so its bytes were stored, not generated), or when it is longer than `limit`
/// bytes.
[[nodiscard]] std::optional<std::string> read_proc_file(std::string_view path, std::size_t limit);

/// The function a sensor reads a kernel-generated file with. The shipped runtime uses read_proc_file, so an interposed
/// libc function can't answer for the kernel; a test passes read_file instead, to feed a regular file of controlled
/// content (read_proc_file refuses regular files, so it can't read a test's temp file). Both readers share this
/// signature.
using ProcReader = std::optional<std::string> (*)(std::string_view, std::size_t);

}  // namespace rasp::util
